const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',book:'M12 5C8 2 3 3 3 3v16s5-1 9 2m0-16c4-3 9-2 9-2v16s-5-1-9 2zm0 0v16',mic:'M12 15a3 3 0 0 0 3-3V6a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3zm-6-4v1a6 6 0 0 0 12 0v-1m-6 7v4m-4 0h8',repeat:'M20 7H7a4 4 0 0 0-4 4v2m17-6-4-4m4 4-4 4M4 17h13a4 4 0 0 0 4-4v-2M4 17l4-4m-4 4 4 4',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',fire:'M12 3c2 5 5 5 5 9 3-2 4 3 2 6-2 4-9 5-13 1-4-5 2-8 2-11 1 2 2 3 3 3 2-2 2-5 1-8z',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',sound:'M11 4 6 8H3v8h3l5 4zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14',save:'M6 3h12v18l-6-4-6 4z',cup:'M4 6h13v7a6.5 6.5 0 0 1-13 0zm13 0h2a3 3 0 0 1 0 6h-2M3 22h15M7 2v1m5-1v1',wave:'M7 13 5 8a1.5 1.5 0 0 1 3-1l2 4-2-7a1.5 1.5 0 0 1 3-1l2 7-1-7a1.5 1.5 0 0 1 3 0l1 8 1-5a1.5 1.5 0 0 1 3 1l-1 8c-1 7-9 9-13 4l-4-5a1.5 1.5 0 0 1 2-2l4 4',auto:'M3 12h18v7H3zm2 0 2-7h10l3 7M7 5v7m9-7v7M6 19v2m12-2v2M5 15h2m10 0h2',bag:'M5 8h14l2 13H3zm3 0V6a4 4 0 0 1 8 0v2',chat:'M4 4h16v12H9l-5 5zm4 5h8m-8 3h5',help:'M9 4h6v5h5v6h-5v5H9v-5H4V9h5z',leaf:'M4 20C-1 7 10 2 21 3c0 15-8 19-17 17zm0 0L16 8',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14zm5-2 6 6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20zm0-15v6l4 2',headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v9H3zm14 0h4v9h-4',gear:'M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1zm3 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zm-5 10 3 3 7-7',trophy:'M7 3h10v8a5 5 0 0 1-10 0zm10 2h4v3a5 5 0 0 1-5 5M7 5H3v3a5 5 0 0 0 5 5m4 3v5m-4 0h8',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20zm0-12v7m0-11v1'};
function icon(n,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const units=[
 {title:'Your first hello',desc:'Make a connection, one word at a time.',icon:'wave',short:'Basics',lessons:['Hello, Kerala','How are you?','Names & goodbyes']},
 {title:'A stop for chaaya',desc:'Tea, coffee, and your first food order.',icon:'cup',short:'Food & drink',lessons:['Tea or water?','Coffee, your way','Make it yours']},
 {title:'Find your way',desc:'Autos, directions, and getting there.',icon:'auto',short:'Getting around',lessons:['Where is it?','Catch your train','Left or right?']},
 {title:'A little shopping',desc:'Ask the price and pick your favourite.',icon:'bag',short:'Shopping',lessons:['How much?','Yes, this one','A better price']},
 {title:'Keep the conversation going',desc:'Slow it down. Ask again. You’ve got this.',icon:'chat',short:'Conversation',lessons:['Say that again','A little slower','Bridge the gap']},
 {title:'When you need a hand',desc:'Useful words for getting help.',icon:'help',short:'Help',lessons:['Ask for help','Find a pharmacy','Feeling unwell']}
];
// Latin script is the learning interface. Native text is the source for bundled Malayalam audio.
const rows=[
 ['Namaskaaram','Hello','na-mas-kaa-ram','നമസ്കാരം','Hold the aa a little longer, as in “father”. A friendly greeting; a simple hello is common too.'],
 ['Nandi','Thank you','nan-di','നന്ദി','Keep both syllables short. Let your tongue touch just behind your upper teeth for d.'],
 ['Sukhamaano?','How are you?','su-kha-maa-no','സുഖമാണോ','Keep the aa long. Let your voice rise gently at the end of the question.'],
 ['Sukham','I’m well','su-kham','സുഖം','A short reply to “Sukhamaano?” Keep the ending light; no extra syllable after m.'],
 ['Ente peru Raghav','My name is Raghav','en-te pay-ru Raghav','എന്റെ പേര് രാഘവ്','Replace Raghav with your name. The e in peru is long and steady: don’t slide into an English “ay”.'],
 ['Naale kaanaam','See you tomorrow','naa-le kaa-naam','നാളെ കാണാം','Hold each aa. The l in naale is made with your tongue curled back slightly.'],
 ['Oru chaaya venam','I’d like a tea','o-ru chaa-ya vay-nam','ഒരു ചായ വേണം','Chaaya has a long aa. Hold the e in venam steady; “vay” is only a rough cue, without a y-glide.'],
 ['Vellam venam','I’d like water','vel-lam vay-nam','വെള്ളം വേണം','Hold the doubled ll briefly with your tongue curled back. It is not the ordinary l in English “let”.'],
 ['Oru kaappi venam','I’d like a coffee','o-ru kaap-pi vay-nam','ഒരു കാപ്പി വേണം','Keep aa long, close your lips briefly for pp, then release. Don’t rush kaappi into “copy”.'],
 ['Kattan chaaya','Black tea','kat-tan chaa-ya','കട്ടൻ ചായ','Hold the doubled tt briefly; curl your tongue back for that t. Kattan means black, without milk.'],
 ['Paal venda','No milk, please','paal vayn-da','പാൽ വേണ്ട','The aa in paal is long. Venda means “don’t want”; venam means “want”. Tone keeps the request friendly.'],
 ['Madhuram venda','No sugar, please','ma-dhu-ram vayn-da','മധുരം വേണ്ട','In a tea order, this asks for no sweetening. Put your tongue near your upper teeth for dh; don’t use English “this”.'],
 ['Evide?','Where?','e-vi-de','എവിടെ','Three light syllables. The d is made with your tongue curled back, rather than touching the teeth.'],
 ['Bus stand evide?','Where is the bus stand?','bus stand e-vi-de','ബസ് സ്റ്റാൻഡ് എവിടെ','Keep “bus stand” in English, then add evide. Mixing familiar English place names is useful here.'],
 ['Railway station evide?','Where is the railway station?','railway station e-vi-de','റെയിൽവേ സ്റ്റേഷൻ എവിടെ','Use your familiar words for railway station, then ask evide with a gentle question ending.'],
 ['Ivide nirthu','Stop here','i-vi-de nir-thu','ഇവിടെ നിർത്തൂ','Ivide means here; evide means where. For th, touch near the upper teeth: it is not English “thin”.'],
 ['Edathottu','To the left','e-da-thot-tu','ഇടത്തോട്ട്','Keep the middle o long and hold the final doubled tt briefly. Use it while giving directions.'],
 ['Valathottu','To the right','va-la-thot-tu','വലത്തോട്ട്','Keep the o long, with a short hold at tt. Pair this with edathottu: left and right.'],
 ['Ethra roopa?','How many rupees?','eth-ra roo-pa','എത്ര രൂപ','Th is a dental t, not English “th”. Hold oo in roopa as in “food”. A useful way to ask a price.'],
 ['Venam','I want it','vay-nam','വേണം','The long e stays steady. Curl your tongue back for n. Say it warmly when accepting something.'],
 ['Venda','I don’t want it','vayn-da','വേണ്ട','Keep the e long and steady. Listen for the different ending: venda declines, venam accepts.'],
 ['Ithu venam','I’d like this','i-thu vay-nam','ഇത് വേണം','Point to the item. The th in ithu is a soft dental sound, often heard closer to d in speech.'],
 ['Kurachu kuraykkamo?','Could you lower the price a little?','ku-ra-chu ku-ray-kkaa-mo','കുറച്ച് കുറയ്ക്കാമോ','Keep the final aa long and the question gentle. Kurachu means “a little”. Use only where bargaining is appropriate.'],
 ['Bill tharumo?','Could I have the bill?','bill tha-ru-mo','ബിൽ തരുമോ','Bill is an English loanword. Touch your tongue near your upper teeth for th, with no English “th” hiss.'],
 ['Manassilaayilla','I didn’t understand','ma-nas-si-laa-yil-la','മനസ്സിലായില്ല','Break it into small chunks: ma-nas-si / laa-yil-la. Hold ss and ll briefly.'],
 ['Veendum parayamo?','Could you say it again?','veen-dum pa-ra-yaa-mo','വീണ്ടും പറയാമോ','Hold ee in veendum and aa in parayamo. A rising, friendly ending makes this a request.'],
 ['Onnu pathukke parayamo?','Could you speak a little slowly?','on-nu pa-thuk-ke pa-ra-yaa-mo','ഒന്ന് പതുക്കെ പറയാമോ','Hold nn and kk briefly. Pathukke means slowly. Practise one word at a time, then join them.'],
 ['Ariyilla','I don’t know','a-ri-yil-la','അറിയില്ല','Keep the first two syllables light and hold ll briefly. Do not turn the r into a strong English r.'],
 ['Enikku Malayalam ariyilla','I don’t know Malayalam','e-nik-ku ma-la-yaa-lam a-ri-yil-la','എനിക്ക് മലയാളം അറിയില്ല','Hold kk in enikku. The l after yaa in Malayalam is a curled-tongue l.'],
 ['English ariyamo?','Do you know English?','English a-ri-yaa-mo','ഇംഗ്ലീഷ് അറിയാമോ','Keep aa long in ariyamo. This asks whether the other person knows English.'],
 ['Sahaayikkoo','Please help','sa-haa-yik-koo','സഹായിക്കൂ','Hold aa and the final oo. Hold kk briefly before releasing into oo.'],
 ['Aashupathri evide?','Where is the hospital?','aa-shu-pa-thri e-vi-de','ആശുപത്രി എവിടെ','Hold the initial aa. Th is made near the upper teeth. Break aashupathri into four small beats.'],
 ['Marunnu venam','I need medicine','ma-run-nu vay-nam','മരുന്ന് വേണം','Hold the doubled nn in marunnu. This is a general request; you still need to explain which medicine.'],
 ['Marunnu kada evide?','Where is the pharmacy?','ma-run-nu ka-da e-vi-de','മരുന്നുകട എവിടെ','Marunnu means medicine; kada means shop. The d in kada is made with a curled-back tongue.'],
 ['Enikku vayar vedana','I have a stomach ache','e-nik-ku va-yar vay-da-na','എനിക്ക് വയർ വേദന','Hold kk in enikku. Vayar is stomach, and vedana is pain. Keep the long e steady.'],
 ['Enikku pani undu','I have a fever','e-nik-ku pa-ni un-du','എനിക്ക് പനി ഉണ്ട്','Pani has a short a and an ordinary n. Keep it distinct from the curled-tongue n in the word for work.']
];
const phrases=[...rows.map((p,i)=>({id:i,unit:Math.floor(i/6),topic:Math.floor(i/6),latin:p[0],english:p[1],say:p[2],native:p[3],tip:p[4]})),...(window.PARAYU_CONTENT?.phrases||[]).map((p,i)=>({...p,id:36+i,unit:Math.min(p.topic,5)}))];
const phraseTopics=[...units.map(u=>u.short),'Stay & comfort','Money & phone','Out & about'];
function phraseTopicIndex(p){return p.topic??p.unit}
function phraseTopic(p){return phraseTopics[phraseTopicIndex(p)]||'Useful phrases'}
let state;try{state=JSON.parse(localStorage.getItem('parayu-v1'))}catch{}
state={xp:0,completed:[],saved:[],savedWords:[],days:{},reviews:{},goal:30,...(state||{})};
state.guestDays ??= {...state.days};
let view='learn',filter='all',query='',session=null,recorder=null,stream=null,recordUrl=null,recordTimer=null,recording=false,audioPlayer=null,toastTimer;
let pronunciationToken=0,pronunciationState=null;
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function persist(){try{localStorage.setItem('parayu-v1',JSON.stringify(state))}catch{toast('Progress could not be saved. Check your browser storage settings.')}}
function todayXP(){return state.days[dateKey()]||0}
function streak(){if(window.ParayuAccount)return window.ParayuAccount.getStreakStats().current;let n=0,d=new Date();if(!state.days[dateKey(d)])d.setDate(d.getDate()-1);while(state.days[dateKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
function award(n){state.xp+=n;const k=dateKey();state.days[k]=(state.days[k]||0)+n;if(!window.ParayuAccount?.recordDay(k))state.guestDays[k]=(state.guestDays[k]||0)+n;persist()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function completedUnit(u){return state.completed.filter(k=>k.startsWith(u+'-')).length}
function nextLesson(){for(let u=0;u<6;u++)for(let l=0;l<3;l++)if(!state.completed.includes(`${u}-${l}`))return[u,l];return[0,0]}
function art(){return `<svg class="hero-art" viewBox="0 0 280 250" fill="none" aria-hidden="true"><ellipse cx="149" cy="235" rx="110" ry="9" fill="#d3dfc4"/><circle cx="201" cy="78" r="54" fill="#e1e9d2"/><path d="M226 232c-2-58 9-116 12-163" stroke="#b2c495" stroke-width="7"/><path d="M236 75c-19-39-51-28-68-16 25-2 49 4 68 16m0 0c10-46 44-36 44-36-17 8-29 21-44 36m0 0c-19-15-50 0-54 20 23-18 37-22 54-20m0 0c16-12 38 1 42 22-20-16-25-22-42-22m0 0c-3-43 4-54 13-58 3 17-1 35-13 58" fill="#9bb487"/><path d="M38 223c11-19 26-26 41-15m-28 13c-3-25-13-28-22-24m38 25c-2-14 4-22 16-24" fill="#96b580"/><path d="M106 209l-10 23m49-24 10 23" stroke="#5d8056" stroke-width="9" stroke-linecap="round"/><path d="M93 230h-9m70 0h10" stroke="#5d8056" stroke-width="8" stroke-linecap="round"/><path d="M68 158c-15 4-26-4-28-14m129 15c14 1 20-10 22-21" stroke="#739966" stroke-width="9" stroke-linecap="round"/><path d="M62 142c0-43 22-65 57-65 40 0 62 29 62 66 0 45-22 74-61 74-36 0-58-27-58-75" fill="#9cb878"/><path d="M78 136c0-36 17-53 42-53 30 0 48 20 48 54 0 34-17 59-45 59-27 0-45-25-45-60" fill="#d8e9b0"/><path d="M119 79c-3-19 7-30 29-31-2 19-11 28-29 31" fill="#648954"/><path d="M121 78c-13-17-25-18-36-14 8 14 19 19 36 14" fill="#89aa68"/><ellipse cx="102" cy="133" rx="4" ry="6" fill="#3c6148"/><ellipse cx="139" cy="133" rx="4" ry="6" fill="#3c6148"/><path d="M111 149c5 6 14 6 19 0" stroke="#3c6148" stroke-width="3" stroke-linecap="round"/><ellipse cx="92" cy="145" rx="7" ry="4" fill="#c4d995"/><ellipse cx="149" cy="145" rx="7" ry="4" fill="#c4d995"/><path d="m113 180 5 13 6-13" fill="#7e9a5d"/><path d="M25 56c0-17 15-26 35-26s35 10 35 26-14 26-34 26l-15 13 2-15C34 76 25 68 25 56" fill="white"/><path d="M42 55c5-7 10-7 13 0m8 0c5-7 10-7 13 0m-25 8c7 7 14 7 21 0" stroke="#7e9f69" stroke-width="2.5" stroke-linecap="round"/><path d="M188 118v-14m-6 7h12m-6-5 4 10m-8 0 8-10" stroke="#c3b36b" stroke-width="2"/><path d="M173 201c5-12 15-12 22-5m-7 20c9-22 20-20 27-14" stroke="#a4bc8b" stroke-width="3" stroke-linecap="round"/></svg>`}
function render(){
 const navs=[['learn','home','Learn'],['practice','mic','Practice'],['phrasebook','book','Phrasebook'],['vocabulary','leaf','Words'],['review','repeat','Review'],['sounds','headphones','Sound studio']];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#learn"><img src="icon.svg" alt="">parayu<span style="color:#a5ba7f">.</span></a><div class="brand-tag">SPEAK A LITTLE KERALA</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,ic,label])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='review'&&duePhrases().length?`<span class="badge">${duePhrases().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="travel-note"><div class="eyebrow">Made for the journey</div><p>Less textbook.<br>More “one chaaya, please.”</p><button data-action="travel">Open travel essentials ${icon('arrow').replace('<svg','<svg style="width:12px;vertical-align:middle"')}</button></div><button class="profile" data-nav="progress"><span class="avatar">YOU</span><div><strong style="font-size:12px">Your little journey</strong><div class="small muted">${state.completed.length<6?'Curious explorer':'Kerala regular'}</div></div>${icon('gear')}</button></div></aside><div class="shell"><header class="topbar"><a class="brand mobile-brand" href="#learn"><img src="icon.svg" alt="">parayu.</a><div class="crumb">Your journey <span style="padding:0 12px">/</span> <strong>${navs.find(n=>n[0]===view)?.[2]||'Your progress'}</strong></div><div class="topstats"><span class="streak" title="Consecutive days with practice">${icon('fire')}<span data-streak-current>${streak()}</span> <span class="small" data-streak-unit>day${streak()===1?'':'s'}</span></span><button class="xp" data-nav="progress" aria-label="Your progress, ${state.xp} XP">${icon('star')}${state.xp} XP</button><button class="account-button" data-account="open" data-account-label>${window.ParayuAccount?.isSignedIn()?'Account':'Log in'}</button></div></header><main id="main" class="content">${view==='learn'?learnView():view==='phrasebook'?phrasebookView():view==='vocabulary'?vocabularyView():view==='practice'?practiceView():view==='review'?reviewView():view==='sounds'?soundView():progressView()}</main></div>`;
 if(view==='vocabulary')renderWordResults();
}
function learnView(){
 const [u,l]=nextLesson(), finished=state.completed.length===18;
 return `<section class="intro rebuild-intro"><div><div class="eyebrow">YOUR EVERYDAY MALAYALAM CLUB</div><h1>Next stop:<br><span>speaking Malayalam.</span></h1><p>A few minutes today. A little more Kerala tomorrow.</p></div><button class="travel-switch" data-action="travel">${icon('auto')} Travel mode ${icon('arrow')}</button></section>
 <div class="grid"><div class="trail-column"><section class="hero new-hero"><div class="hero-copy"><span class="hero-kicker">${finished?'LOOK HOW FAR YOU’VE COME':state.completed.length?'PICK UP WHERE YOU LEFT OFF':'LET’S GET YOU TALKING'}</span><h2>${finished?'Kerala, here you come.':state.completed.length?esc(units[u].lessons[l]):'Start small.<br>Speak sooner.'}</h2><p>${finished?'Revisit a favourite lesson or try a real-world conversation.':'Useful words. A little practice.<br>Your first conversation starts here.'}</p><button class="btn" data-start="${u}-${l}">${finished?'Practise again':state.completed.length?'Continue lesson':'Start your first lesson'} ${icon('arrow')}</button><div class="hero-time">${icon('clock')} 3–5 minutes <span>·</span> No alphabet needed</div></div><div class="mascot-stage">${art()}<span class="mascot-speech">Namaskaaram!</span><span class="mascot-caption">That’s your first hello.</span></div></section>
 <div class="sectionhead"><div><span class="eyebrow trail-eyebrow">ONE CONVERSATION AT A TIME</span><h2>Your learning trail</h2></div><span class="course-progress">${state.completed.length}<span> / 18 lessons</span></span></div>
 <section class="trail-units" aria-label="Learning units">${units.map((x,i)=>`<article class="trail-unit unit-tone-${i} ${i===u?'next-unit':''}"><button class="unit-summary" data-unit="${i}" aria-label="Open unit ${i+1}: ${x.title}"><span class="uniticon">${icon(x.icon)}</span><div><span class="eyebrow">UNIT ${String(i+1).padStart(2,'0')} · ${x.short}</span><h3>${x.title}</h3><p>${x.desc}</p></div><span class="unit-count">${completedUnit(i)===3?icon('check'):completedUnit(i)+'/3'}</span></button><div class="trail-lessons">${x.lessons.map((name,j)=>{const done=state.completed.includes(`${i}-${j}`),next=i===u&&j===l;return `<button class="trail-lesson ${done?'lesson-done':''} ${next?'lesson-next':''}" data-start="${i}-${j}"><span class="lesson-node">${icon(done?'check':j===2?'mic':'chat')}</span><span class="lesson-name">${name}</span><span class="lesson-status">${done?'Practise again':next?'START HERE':j===2?'Say it out loud':'Learn & speak'}</span></button>`}).join('')}</div></article>`).join('')}</section>
 <div class="sectionhead"><div><span class="eyebrow trail-eyebrow">PUT YOUR WORDS TO WORK</span><h2>A little real-world rehearsal</h2></div><button class="textbtn" data-nav="practice">Explore ${icon('arrow').replace('<svg','<svg style="width:14px;vertical-align:middle"')}</button></div>${scenarioCards(false)}</div>
 <aside class="sidecol">${goalCard()}${dailyPhrase()}<section class="card sound-promo"><span class="promo-icon">${icon('headphones')}</span><div class="eyebrow">SOUNDS LIKE PROGRESS</div><h3>Get your tongue<br>around it.</h3><p>Long vowels, tiny pauses, and the famous “zh”. We’ll break it down.</p><button class="textbtn" data-nav="sounds">Visit the sound studio →</button></section><section class="pocket-promo"><span>${icon('save')}</span><div><h3>Your pocket Malayalam</h3><p>Keep useful phrases a tap away.</p><button class="textbtn" data-action="saved-phrases">${state.saved.length} saved phrases →</button></div></section><p class="rail-note">${icon('leaf')} Learn at your pace.<br>Every conversation counts.</p></aside></div>${footer()}`
}
function goalCard(){let d=new Date(),day=d.getDay(),monday=new Date(d);monday.setDate(d.getDate()-((day+6)%7));return `<section class="card dailygoal"><div class="cardhead"><h3>A little every day</h3>${icon('star')}</div><div class="goalnum">${todayXP()} <small>/ ${state.goal} XP today</small></div><div class="progressbar"><i style="width:${Math.min(todayXP()/state.goal*100,100)}%"></i></div><div class="small muted" style="font-size:10px">${todayXP()>=state.goal?'Daily goal reached. Look at you go!':'A few minutes can take you places.'}</div><div class="week">${['M','T','W','T','F','S','S'].map((x,i)=>{const a=new Date(monday);a.setDate(monday.getDate()+i);return `<div class="${dateKey(a)===dateKey()?'today':''} ${state.days[dateKey(a)]?'done':''}"><span>${state.days[dateKey(a)]?'✓':dateKey(a)===dateKey()?'•':''}</span>${x}</div>`}).join('')}</div></section>`}
function dailyPhrase(){const day=Math.floor(Date.now()/86400000),p=phrases[[6,7,18,15,25,10,14][day%7]];return `<section class="card phrase-day"><div class="eyebrow">TODAY’S LITTLE PHRASE</div><div class="daily-phrase-icon">${icon(units[p.unit].icon)}</div><h2>${p.latin}</h2><div class="phonetic">${p.say}</div><p class="translation">“${p.english}”</p><div class="phrase-bottom"><button class="textbtn" data-phrase="${p.id}">Try saying it →</button><button class="soundbtn" aria-label="Hear ${p.latin}" data-speak="${p.id}">${icon('sound')}</button></div></section>`}
const scenarios=[{title:'At the tea stall',desc:'One tea. A little conversation.',icon:'cup',tag:'FOOD & DRINK',steps:[{speaker:'Tea stall owner',line:'Chaaya veno?',translation:'Would you like tea?',prompt:'Ask for one tea.',answer:6,options:[6,7,8]},{speaker:'Tea stall owner',line:'Paal veno?',translation:'Would you like milk?',prompt:'Ask for no milk.',answer:10,options:[10,19,7]},{speaker:'Tea stall owner',line:'Vere enthenkilum?',translation:'Anything else?',prompt:'Politely decline.',answer:20,options:[20,19,6]}]},
 {title:'On the move',desc:'Find your way, a phrase at a time.',icon:'auto',tag:'GETTING AROUND',steps:[{speaker:'You’re outside your hotel',line:'Your train leaves soon.',translation:'A passerby offers to help.',prompt:'Ask where the railway station is.',answer:14,options:[13,14,31]},{speaker:'Auto driver',line:'Edathotto, valathotto?',translation:'To the left or to the right?',prompt:'Tell them to go left.',answer:16,options:[17,16,15]},{speaker:'Auto driver',line:'Ivide mathiyo?',translation:'Is here okay?',prompt:'Ask the driver to stop here.',answer:15,options:[15,12,18]}]},
 {title:'At the market',desc:'A good find. An even better chat.',icon:'bag',tag:'SHOPPING',steps:[{speaker:'You see something you like',line:'Time to try a little Malayalam.',translation:'The shopkeeper smiles.',prompt:'Ask the price in rupees.',answer:18,options:[18,21,23]},{speaker:'Shopkeeper',line:'Irunnuuru roopa.',translation:'Two hundred rupees.',prompt:'Ask if the price can be lowered a little.',answer:22,options:[20,22,18]},{speaker:'Shopkeeper',line:'Sheri.',translation:'Okay.',prompt:'Say you would like this item.',answer:21,options:[21,20,23]}]}];
function scenarioCards(full){return `<div class="${full?'practice-layout':'scenario-grid'}">${scenarios.map((s,i)=>`<button class="scenario" data-role="${i}">${icon(s.icon)}${full?`<div class="eyebrow muted">${s.tag}</div>`:''}<h3>${s.title}</h3><p>${s.desc}</p>${full?'<p style="margin-top:25px;color:#21674f">3 turns · Guided roleplay →</p>':''}</button>`).join('')}</div>`}
function footer(){return `<footer class="footer"><span>Made for real conversations, not perfect scores.</span><button class="textbtn" data-action="about">Our approach & sources</button></footer>`}
function phraseCard(p){return `<article class="phrase-item"><div class="phrase-top"><span class="eyebrow muted" style="font-size:8px">${phraseTopic(p)}</span><div><button class="iconbtn ${state.saved.includes(p.id)?'saved':''}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.latin)}" aria-pressed="${state.saved.includes(p.id)}" data-save="${p.id}">${icon('save')}</button><button class="iconbtn" aria-label="Hear ${esc(p.latin)}" data-speak="${p.id}">${icon('sound')}</button></div></div><h3>${esc(p.latin)}</h3><div class="phonetic">${esc(p.say)}</div><p class="translation">${esc(p.english)}</p><p class="tip">${esc(p.tip)}</p>${phraseBreakdown(p.id)}<button class="textbtn" data-phrase="${p.id}" style="margin-top:10px">Say it out loud →</button></article>`}
function filteredPhrases(){return phrases.filter(p=>(filter==='all'||filter==='saved'&&state.saved.includes(p.id)||String(phraseTopicIndex(p))===filter)&&(`${p.latin} ${p.english} ${phraseTopic(p)}`.toLowerCase().includes(query.toLowerCase())))}
function phrasebookView(){return `<div class="page-title"><div class="eyebrow muted" style="margin-bottom:12px">Your pocket companion</div><h1>A phrase for every day.</h1><p>Find it. Say it. Get on with your adventure.</p></div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search ‘water’, ‘how much’, ‘bus’…" aria-label="Search Malayalam phrases" value="${esc(query)}"></label><div class="chips">${[['all','All phrases'],['saved','Saved'],...phraseTopics.map((name,i)=>[String(i),name])].map(([id,name])=>`<button class="chip ${filter===id?'active':''}" aria-pressed="${filter===id}" data-filter="${id}">${name}${id==='saved'?` · ${state.saved.length}`:''}</button>`).join('')}</div><p class="result-count" id="phrase-count">${filteredPhrases().length} of ${phrases.length} phrases</p><div class="phrase-list" id="phrase-list">${phraseResults()}</div>${footer()}`}
function phraseResults(){const a=filteredPhrases();return a.length?a.map(phraseCard).join(''):`<div class="empty">${filter==='saved'&&!query?'Your pocket is empty. Tap the bookmark beside a phrase to keep it here.':'No phrases found. Try “tea”, “help”, or a shorter search.'}</div>`}
function practiceView(){return `<div class="page-title"><div class="eyebrow muted" style="margin-bottom:12px">A little rehearsal goes a long way</div><h1>Let’s have a conversation.</h1><p>Try a real-world situation. Choose your reply, then say it out loud.</p></div>${scenarioCards(true)}<section class="card" style="margin-top:24px;display:flex;gap:20px;align-items:center"><span class="uniticon">${icon('mic')}</span><div><h3>Your voice. Your pace.</h3><p class="small muted" style="margin-top:6px">Record yourself and listen back. No microphone? Read the phrase aloud and use the pronunciation checklist.</p><button class="textbtn" data-nav="sounds" style="margin-top:9px">Open the sound studio →</button></div></section>${footer()}`}
function learnedIds(){return [...new Set(state.completed.flatMap(k=>{const[u,l]=k.split('-').map(Number);return[u*6+l*2,u*6+l*2+1]}))]}
function duePhrases(){return phrases.filter(p=>learnedIds().includes(p.id)&&(!state.reviews[p.id]||state.reviews[p.id]<=Date.now()))}
function reviewView(){const a=duePhrases();return `<div class="page-title"><div class="eyebrow muted" style="margin-bottom:12px">Make the words stick</div><h1>A familiar little face.</h1><p>Revisit what you’ve learned. A little repetition makes the words familiar.</p></div><section class="hero" style="min-height:200px"><div class="hero-copy"><div class="eyebrow">${a.length} PHRASES READY TO REVIEW</div><h2>${a.length?'A quick refresh?':'You’re all caught up.'}</h2><p>${a.length?'Recall the meaning, then check yourself. Small repeats make a big difference.':learnedIds().length?'Come back when your next phrases are due. You can revisit any lesson whenever you like.':'Complete your first lesson to add phrases to your review collection.'}</p><button class="btn" ${a.length?'data-action="start-review"':'data-nav="learn"'}>${a.length?'Start review':'Explore lessons'} ${icon('arrow')}</button></div>${art()}</section>${state.saved.length?`<div class="sectionhead"><h2>Saved for later</h2><span class="small muted">${state.saved.length} phrases</span></div><div class="phrase-list">${state.saved.map(id=>phraseCard(phrases[id])).join('')}</div>`:''}${footer()}`}
const soundTips=[['01 · Give vowels some room','Long sounds, steady sounds.','aa · ee · oo','Aa sounds like the a in “father”, ee like “feet”, and oo like “food”. Hold them longer than short vowels. Long e (the “vay” cue) stays steady rather than gliding into y.','Kaappi · coffee',8],['02 · Don’t rush the middle','Double letters. Tiny hold.','kap-pi → kaap-pi','With pp, kk, nn or ll, hold the consonant a little longer before releasing it. The aa in kaappi also stays long. Small timing differences can change a word.','Vellam · water',7],['03 · Meet your tongue','Straight or curled?','dental t · curled L','For dental t (written th in many phrases), touch your tongue near the upper teeth. It isn’t the English “th” in “thin”. Curled-tongue sounds bring the tip farther back. Vellam uses a curled, doubled l.','Ivide nirthu · stop here',15],['04 · The famous “zh”','A new sound, not a z.','mazha · rain','The zh in mazha is a curled-tongue sound with no exact English equivalent. Bring your tongue tip back toward the roof without firmly closing the airflow. Avoid saying z-h as two sounds.','Hear mazha · rain',null]];
function soundView(){return `<div class="page-title"><div class="eyebrow muted" style="margin-bottom:12px">Less guessing. More speaking.</div><h1>Get a feel for the sounds.</h1><p>Easy mouth-position tips. Latin letters. Your own voice.</p></div><div class="lab-grid">${soundTips.map(([num,title,example,text,label,id])=>`<article class="lab-card"><div class="lab-number eyebrow">${num}</div><h2>${title}</h2><div class="lab-example">${example}</div><p>${text}</p>${id!==null?`<button class="textbtn" data-phrase="${id}" style="margin-top:17px">Practise: ${label} →</button>`:`<div class="audiocontrols" style="justify-content:flex-start;margin-top:17px"><button class="btn light" data-speak="mazha">${icon('sound')} ${label}</button><button class="btn light" data-slow="mazha">${icon('clock')} Slower</button></div>`}</article>`).join('')}</div><div class="notice">Pronunciation cues are approximations, not English spellings. Regional speech varies. Every phrase has a built-in Malayalam voice, at normal and slower speeds. Listen, repeat, and record yourself. No voice installation needed.</div>${footer()}`}
function progressView(){return `<div class="page-title"><div class="eyebrow muted" style="margin-bottom:12px">Every little word counts</div><h1>Your Kerala story.</h1><p>Lessons, XP, and saved words are kept in this browser. Log in to sync your streak across devices.</p></div><div class="statsgrid"><div class="statbox"><strong>${state.xp}</strong><span>Total XP earned</span></div><div class="statbox"><strong>${state.completed.length}/18</strong><span>Lessons completed</span></div><div class="statbox"><strong>${learnedIds().length}</strong><span>Phrases learned</span></div></div>${window.ParayuAccount?.streakCard()||''}${goalCard()}<div class="settingsrow"><div><h3>Daily goal</h3><p class="small muted">A pace that fits your day.</p></div><select id="goal" aria-label="Daily XP goal">${[15,30,60].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} XP · ${n===15?'Easy does it':n===30?'Little by little':'Let’s do this'}</option>`).join('')}</select></div><div class="settingsrow"><div><h3>Take your progress with you</h3><p class="small muted">Export a backup or restore it in another browser.</p></div><div style="display:flex;gap:10px"><button class="textbtn" data-action="export">Export</button><button class="textbtn" data-action="import">Import</button><input id="import-file" type="file" accept="application/json" hidden></div></div><div class="settingsrow"><div><h3>Start a new journey</h3><p class="small muted">Clear lessons, XP, reviews, saved phrases, and saved words.</p></div><button class="textbtn" data-action="reset">Reset progress</button></div><div class="notice">Install tip: use your browser’s “Add to Home screen” or “Install app”. After your first online visit, lessons and the phrasebook work offline. Use Install & offline to download every pronunciation clip before travelling. Microphone recordings stay on your device and are discarded when you close speaking practice.</div>${footer()}`}
function navigate(v){stopPronunciation();view=v;history.replaceState(null,'','#'+v);render();window.scrollTo({top:0,behavior:'instant'})}
function openDialog(html){cleanupRecording();$('#dialog').innerHTML=`<div class="modal">${html}</div>`;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0}
function closeDialog(){cleanupRecording();session=null;$('#dialog').close()}
function modalHeader(title,progress=''){return `<div class="modalhead"><span class="eyebrow">${title}</span>${progress}<button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div>`}
function openUnit(u){const x=units[u];openDialog(`${modalHeader('UNIT '+String(u+1).padStart(2,'0'))}<h1 style="font-size:29px">${x.title}</h1><p class="muted" style="margin-top:10px">${x.desc}</p><div class="lessonpicker">${x.lessons.map((n,l)=>`<button data-start="${u}-${l}"><span class="num">${state.completed.includes(`${u}-${l}`)?'✓':l+1}</span><div><strong>${n}</strong><small>${phrases[u*6+l*2].latin} · ${phrases[u*6+l*2+1].latin}</small></div><span style="margin-left:auto;width:16px">${icon('arrow')}</span></button>`).join('')}</div><p class="small muted">Every lesson is open. Follow the trail or jump to what you need.</p>`)}
function startLesson(u,l){session={kind:'lesson',u,l,step:0,correct:0,answered:false};lessonStep()}
function lessonPhraseId(s=session){return s.u*6+s.l*2+(s.step>=3?1:0)}
function lessonStep(){
 const s=session,p=phrases[lessonPhraseId(s)],learn=s.step===0||s.step===3,quiz=s.step===1||s.step===4,build=s.step===5;let body;
 if(learn){body=`<div class="lessonmain"><div class="lessonlabel">${s.step===0?'MEET YOUR FIRST PHRASE':'ONE MORE FOR YOUR POCKET'}</div><span class="lesson-big-icon">${icon(units[s.u].icon)}</span><h1>${p.latin}</h1><div class="phonetic">${p.say}</div><p class="translation">“${p.english}”</p>${audioControls(p.id)}<div class="tipbox"><strong>Pronunciation tip</strong>${p.tip}</div>${phraseBreakdown(p.id,true)}</div>`}
 else if(quiz){s.options=makeChoices(p);body=`<div class="lessonmain"><div class="lessonlabel">WHAT WOULD YOU SAY?</div><p class="muted small">Choose the Malayalam reply for…</p><h2>“${p.english}”</h2><div class="choices">${s.options.map((id,i)=>`<button class="choice" data-answer="${id}"><span>${i+1}</span>${phrases[id].latin}</button>`).join('')}</div><div id="feedback" role="status"></div></div>`}
 else if(build){s.wordBank=shuffle(p.latin.split(' '));s.wordOrder=[];body=`<div class="lessonmain"><div class="lessonlabel">PUT IT TOGETHER</div><p class="muted small">Build the phrase for…</p><h2>“${p.english}”</h2><div id="word-answer" class="word-answer" aria-live="polite"><span>Tap the words in order</span></div><div class="word-bank">${s.wordBank.map((w,i)=>`<button class="word-chip" data-word="${i}">${w}</button>`).join('')}</div><button class="textbtn" data-action="clear-words">Clear words</button><div id="feedback" role="status"></div></div>`}
 else{body=speakingUI(p,s.step===2?'YOUR FIRST PHRASE, IN YOUR VOICE':'SAY IT. MAKE IT YOURS.');}
 openDialog(`${modalHeader(units[s.u].lessons[s.l],`<div class="progressbar"><i style="width:${s.step/7*100}%"></i></div><span class="step-label">${s.step+1}/7</span>`)}${body}<div class="modalfoot"><p>${s.step===2||s.step===6?'Speak aloud or record. Your pace, your voice.':'Little by little. You’re getting there.'}</p><button class="btn" id="lesson-next" data-action="${build?'check-words':'lesson-next'}" ${quiz||build?'disabled':''}>${s.step===6?'Finish lesson':build?'Check phrase':'Continue'} ${icon('arrow')}</button></div>`)
}
function addWord(index){const s=session;if(!s||s.kind!=='lesson'||s.step!==5||s.answered||s.wordOrder.includes(index))return;s.wordOrder.push(index);renderWordOrder()}
function renderWordOrder(){const s=session;$('#word-answer').innerHTML=s.wordOrder.length?s.wordOrder.map(i=>`<button class="word-chip selected" data-remove-word="${i}">${esc(s.wordBank[i])}</button>`).join(''):'<span>Tap the words in order</span>';$$('[data-word]').forEach(b=>b.disabled=s.wordOrder.includes(+b.dataset.word));$('#lesson-next').disabled=s.wordOrder.length!==s.wordBank.length}
function checkWords(){const s=session,p=phrases[lessonPhraseId(s)],actual=s.wordOrder.map(i=>s.wordBank[i]).join(' '),good=actual===p.latin;$('#feedback').innerHTML=`<div class="feedback ${good?'':'error'}"><strong>${good?'That’s your phrase. Now say it aloud.':'A little switch around…'}</strong><p>${good?p.latin:'The phrase is: '+p.latin}</p>${good?'':'<p>Try the order once more.</p>'}</div>`;if(good){s.answered=true;$('#lesson-next').dataset.action='lesson-next';$('#lesson-next').innerHTML=`Continue ${icon('arrow')}`;$$('[data-remove-word]').forEach(b=>b.disabled=true)}else{s.wordOrder=[];renderWordOrder()}}

function makeChoices(p){const ids=[p.id];for(let offset=1;ids.length<3;offset++){const id=(p.id+offset*5)%phrases.length;if(!ids.includes(id))ids.push(id)}return shuffle(ids)}
function shuffle(a){const result=[...a];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function audioControls(id){return `<div class="audiocontrols"><button class="btn light" data-speak="${id}">${icon('sound')} Hear it</button><button class="btn light" data-slow="${id}">${icon('clock')} A little slower</button><button class="audio-stop" id="audio-stop" data-action="audio-stop" disabled aria-label="Stop pronunciation audio">Stop</button></div><div class="audio-note" id="audio-note" role="status">Malayalam voice included · listen normally or a little slower.</div>`}
function speakingUI(p,title){return `<div class="lessonmain"><div class="lessonlabel">${title}</div><h1>${p.latin}</h1><div class="phonetic">${p.say}</div><p class="translation">“${p.english}”</p>${audioControls(p.id)}<div class="recordarea"><button class="recordbtn" data-action="record" id="record-btn" aria-label="Record yourself">${icon('mic')}</button><p class="record-label" id="record-label">Tap to record · up to 30 seconds</p><div id="record-result"></div></div><div class="tipbox"><strong>Your pronunciation cue</strong>${p.tip}</div>${phraseBreakdown(p.id)}<div class="checklist"><label><input type="checkbox"> I said the whole phrase out loud.</label><label><input type="checkbox"> I tried the vowel lengths and consonant holds.</label></div><p class="audio-note">Recordings stay on your device. Compare your rhythm and use the tips; this app doesn’t grade your accent.</p></div>`}
function answer(id,button){const s=session;if(!s||s.answered)return;s.answered=true;const p=phrases[lessonPhraseId(s)],good=id===p.id;if(good)s.correct++;$$('.choice').forEach(b=>{b.disabled=true;if(Number(b.dataset.answer)===p.id)b.classList.add('correct')});if(!good)button.classList.add('wrong');$('#feedback').innerHTML=`<div class="feedback ${good?'':'error'}"><strong>${good?'Exactly. Give it a try aloud.':'Here’s the reply you’re looking for.'}</strong><p>${p.latin} · ${p.english}</p><p class="phonetic">${p.say}</p>${phraseBreakdown(p.id)}</div>`;$('#lesson-next').disabled=false}
function $$(s){return [...document.querySelectorAll(s)]}
function lessonNext(){if(session.step<6){session.step++;session.answered=false;lessonStep();return}const s=session,key=`${s.u}-${s.l}`,first=!state.completed.includes(key),earned=first?20:5;state.completed=Array.from(new Set([...state.completed,key]));[s.u*6+s.l*2,s.u*6+s.l*2+1].forEach(id=>{state.reviews[id]=Date.now()+86400000});award(earned);render();openDialog(`${modalHeader('A little more confident')}<div class="completion"><div class="medal" style="color:#98b86e">${icon('trophy').replace('<svg','<svg style="width:75px;height:75px"')}</div><h1>You’re a little more local.</h1><p>${esc(units[s.u].lessons[s.l])} · ${first?'Two new phrases for your pocket.':'A familiar phrase feels even better.'}</p><div class="finishstats"><div><strong>+${earned}</strong><span>XP EARNED</span></div><div><strong>${s.correct}/2</strong><span>QUIZ RECALL</span></div></div><p class="small">Your phrases return for review tomorrow.</p></div><div class="modalfoot"><button class="textbtn" data-action="close">Back to your trail</button><button class="btn" data-action="next-lesson">Keep going ${icon('arrow')}</button></div>`);session={kind:'finished'}}
function openPhrase(id){const p=phrases[id];openDialog(`${modalHeader(phraseTopic(p))}${speakingUI(p,'A phrase for your pocket')}<div class="modalfoot"><button class="textbtn" data-save="${id}">${state.saved.includes(id)?'✓ Saved':'Save phrase'}</button><button class="btn" data-action="close">Done ${icon('check')}</button></div>`)}
function setPronunciationStatus(message){const note=$('#audio-note');if(note)note.textContent=message;const live=$('#audio-live');if(live)live.textContent=message}
function stopPronunciation(){pronunciationToken++;const player=$('#pronunciation-audio');if(player){player.onplaying=null;player.onended=null;player.onerror=null;player.pause();try{player.currentTime=0}catch{}}pronunciationState=null;$$('[data-speak],[data-slow],[data-word-audio],[data-example-audio]').forEach(b=>b.classList.remove('is-speaking'));if($('#audio-stop'))$('#audio-stop').disabled=true;if($('#playback-bar'))$('#playback-bar').hidden=true;setPronunciationStatus('Malayalam voice included · listen normally or a little slower.')}
function speak(id,slow=false){
 const isExample=id==='mazha',vocabMatch=typeof id==='string'?id.match(/^(word|example):(v[a-f0-9]{10})$/):null,vocab=vocabMatch?(window.PARAYU_CONTENT?.vocabulary||[]).find(w=>w.id===vocabMatch[2]):null;if(vocabMatch&&!vocab)return;if(!isExample&&!vocab&&(!Number.isInteger(id)||!phrases[id]))return;
 if(recording){toast('Stop recording before playing the example.');return}
 stopPronunciation();if(audioPlayer)audioPlayer.pause();
 const player=$('#pronunciation-audio');if(!player){toast('The audio player could not start. Please reload the app.');return}
 const token=pronunciationToken,label=vocab?(vocabMatch[1]==='example'?vocab.sentence:vocab.latin):isExample?'Mazha':phrases[id].latin,key=vocab?'vocabulary/'+vocab.id+'-'+vocabMatch[1]:isExample?'mazha':'phrase-'+String(id).padStart(2,'0');
 pronunciationState={id,slow};player.src='audio/'+key+(slow&&!vocab?'-slow':'')+'.mp3';player.playbackRate=slow&&vocab?.78:1;player.preservesPitch=true;player.preload='auto';
 const current=()=>token===pronunciationToken;
 player.onplaying=()=>{if(!current())return;setPronunciationStatus('Playing in Malayalam · '+(slow?'slower pace':'normal pace'));$$(`[data-${slow?'slow':'speak'}="${id}"]`).forEach(b=>b.classList.add('is-speaking'));if($('#audio-stop'))$('#audio-stop').disabled=false;if($('#playback-label'))$('#playback-label').textContent=label;if($('#playback-speed'))$('#playback-speed').textContent=slow?'Malayalam · slower pace':'Malayalam · normal pace';if($('#playback-bar'))$('#playback-bar').hidden=false;};
 player.onended=()=>{if(!current())return;stopPronunciation();setPronunciationStatus('Heard it? Try saying it aloud, then listen again.')};
 player.onerror=()=>{if(!current())return;stopPronunciation();setPronunciationStatus('Couldn’t load this clip. Please reconnect and try again.');toast('Couldn’t load the pronunciation audio. Please reconnect and try again.')};
 const result=player.play();if(result?.catch)result.catch(error=>{if(!current())return;stopPronunciation();if(error.name==='NotAllowedError'){setPronunciationStatus('Your browser paused audio. Tap Hear it once more.');toast('Tap Hear it again to allow audio playback.')}else if(error.name!=='AbortError'){setPronunciationStatus('Audio couldn’t play. Please reconnect and try again.');toast('Audio couldn’t play. Please reconnect and try again.')}});
}
function cleanupRecording(){stopPronunciation();clearTimeout(recordTimer);if(recorder&&recorder.state!=='inactive'){recorder.onstop=null;recorder.stop()}stream?.getTracks().forEach(t=>t.stop());if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=null;recorder=null;stream=null;recording=false;if(audioPlayer){audioPlayer.pause();audioPlayer=null}}
async function toggleRecording(){if(recording){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording isn’t available in this browser. Read it aloud and use the checklist.');return}const button=$('#record-btn');if(!button)return;button.disabled=true;stopPronunciation();if(audioPlayer){audioPlayer.pause();audioPlayer=null}const activeDialogContent=$('#dialog').firstElementChild;try{const media=await navigator.mediaDevices.getUserMedia({audio:true});if(!$('#dialog').open||$('#dialog').firstElementChild!==activeDialogContent){media.getTracks().forEach(t=>t.stop());return}stream=media;if(recordUrl)URL.revokeObjectURL(recordUrl);const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{clearTimeout(recordTimer);recording=false;stream?.getTracks().forEach(t=>t.stop());button.classList.remove('recording');button.setAttribute('aria-label','Record again');$('#record-label').textContent='Listen back. Try again whenever you like.';const blob=new Blob(chunks,{type:recorder.mimeType});recordUrl=URL.createObjectURL(blob);$('#record-result').innerHTML=`<audio controls aria-label="Your pronunciation recording"></audio>`;audioPlayer=$('#record-result audio');audioPlayer.src=recordUrl};recorder.start();recording=true;button.classList.add('recording');button.setAttribute('aria-label','Stop recording');$('#record-label').textContent='Recording… Tap to stop.';$('#record-result').innerHTML='';recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},30000)}catch(e){toast(e.name==='NotAllowedError'?'Microphone access was denied. Allow it in browser settings, or practise aloud.':'Could not access a microphone. Check your device, or practise aloud.')}finally{button.disabled=false}}
function startRole(i){session={kind:'role',i,step:0,correct:0,answered:false};roleStep()}
function roleStep(){const s=session,r=scenarios[s.i],step=r.steps[s.step];openDialog(`${modalHeader(r.title,`<span class="step-label">${s.step+1} / 3 turns</span>`)}<div class="lessonmain"><div class="lessonlabel">Choose a reply. Then say it.</div><div class="rolecontext"><strong>${step.speaker.toUpperCase()}</strong><p>“${step.line}”</p><p class="small muted">${step.translation}</p></div><h2 style="font-size:21px">${step.prompt}</h2><div class="choices">${shuffle(step.options).map((id,i)=>`<button class="choice" data-role-answer="${id}"><span>${i+1}</span>${phrases[id].latin}</button>`).join('')}</div><div id="feedback" role="status"></div></div><div class="modalfoot"><p>Guided roleplay · 3 real-world turns</p><button class="btn" id="role-next" data-action="role-next" disabled>Continue ${icon('arrow')}</button></div>`)}
function roleAnswer(id,b){if(session.answered)return;session.answered=true;const p=phrases[scenarios[session.i].steps[session.step].answer],good=id===p.id;if(good)session.correct++;$$('.choice').forEach(x=>{x.disabled=true;if(Number(x.dataset.roleAnswer)===p.id)x.classList.add('correct')});if(!good)b.classList.add('wrong');$('#feedback').innerHTML=`<div class="feedback ${good?'':'error'}"><strong>${good?'Exactly. Now say your reply aloud.':'A useful reply here is:'}</strong><p style="margin-top:7px;font-size:17px">${p.latin}</p><p class="phonetic">${p.say}</p><p>${p.english}</p><p class="small" style="margin:10px 0">${p.tip}</p><button class="textbtn" data-speak="${p.id}">Hear it ${icon('sound').replace('<svg','<svg style="width:14px;vertical-align:middle"')}</button>${phraseBreakdown(p.id)}</div>`;$('#role-next').disabled=false}
function roleNext(){if(session.step<2){session.step++;session.answered=false;roleStep()}else{const s=session;award(10);render();openDialog(`${modalHeader('Conversation complete')}<div class="completion"><div class="medal" style="color:#9cba7b">${icon('chat').replace('<svg','<svg style="width:65px;height:65px"')}</div><h1>That’s a conversation.</h1><p>Three turns closer to a real-world chat.</p><div class="finishstats"><div><strong>+10</strong><span>XP EARNED</span></div><div><strong>${s.correct}/3</strong><span>REPLIES RECALLED</span></div></div><p class="small">Choice recall reflects your answers, not pronunciation.</p></div><div class="modalfoot"><button class="textbtn" data-action="close">Back to practice</button><button class="btn" data-role="${s.i}">Try again ${icon('repeat')}</button></div>`);session=null}}
function startReview(){const ids=duePhrases().map(p=>p.id);if(!ids.length)return;session={kind:'review',ids,step:0,good:0,revealed:false};reviewStep()}
function reviewStep(){const s=session,p=phrases[s.ids[s.step]];openDialog(`${modalHeader('A little refresh',`<span class="step-label">${s.step+1} / ${s.ids.length}</span>`)}<div class="lessonmain"><div class="lessonlabel">Say it from memory</div><p class="muted">How would you say…</p><h2 style="margin-top:30px">“${p.english}”</h2><div id="review-answer"><button class="btn light" data-action="reveal">Show the phrase</button></div></div><div class="modalfoot" id="review-foot"><p>Try it aloud before you peek.</p></div>`)}
function revealReview(){const p=phrases[session.ids[session.step]];$('#review-answer').innerHTML=`<h1 style="margin-top:15px">${p.latin}</h1><p class="phonetic">${p.say}</p><p class="small muted" style="margin:18px 0">${p.tip}</p>${audioControls(p.id)}${phraseBreakdown(p.id)}`;$('#review-foot').innerHTML=`<button class="btn light" data-review="again">Still learning</button><button class="btn" data-review="good">I remembered ${icon('check')}</button>`}
function rateReview(good){const s=session,id=s.ids[s.step];state.reviews[id]=Date.now()+(good?3*86400000:10*60000);if(good)s.good++;persist();if(++s.step<s.ids.length){reviewStep()}else{award(5);render();openDialog(`${modalHeader('Refresh complete')}<div class="completion"><h1>Those words feel closer.</h1><p>${s.good} of ${s.ids.length} phrases remembered.<br>+5 XP for showing up.</p><p class="small">Remembered phrases return in 3 days.<br>Still-learning phrases return in 10 minutes.</p></div><div class="modalfoot"><p>Practice makes familiar.</p><button class="btn" data-action="close">Done ${icon('check')}</button></div>`);session=null}}
function about(){openDialog(`${modalHeader('A little about Parayu')}<div class="sources"><h1 style="font-size:29px">Made for the conversations.</h1><p>Parayu means “say” or “tell” as a polite request. This starter course teaches practical Malayalam for visitors: 18 short lessons, 144 phrases, 1,000 vocabulary words, and 3 guided roleplays. Every learning screen uses Latin script.</p><p>The vocabulary collection is curated and informed by written-corpus frequency, rather than a definitive spoken top-1,000 ranking. Each word has a meaning, a short original teaching example, and audio. See the word-bank source notes for attribution and selection details.</p><p>The sound cues are simple approximations. Long e is shown roughly as “vay” without the final glide; aa, ee and oo mark long vowels. Tips explain tongue positions where Latin letters fall short. Usage and pronunciation vary across Kerala.</p><p>Travel vocabulary was checked against <a href="https://www.keralatourism.org/faq/hundred-malayalam-words-which-will-help-you" target="_blank" rel="noopener">Kerala Tourism’s visitor vocabulary</a> and <a href="https://www.keralatourism.org/faq/the-must-know-10-malayalam-words-when-you-visit-kerala" target="_blank" rel="noopener">essential travel phrases</a>. Pronunciation guidance draws on <a href="https://malayalam.la.utexas.edu/resources/pronunciation-the-basics/" target="_blank" rel="noopener">UT Austin’s Malayalam resources</a> and <a href="https://malayalam.la.utexas.edu/resources/pronunciation-beyond-the-basics/" target="_blank" rel="noopener">Beyond the Basics</a>, by Donald R. Davis, Jr. and Darsana Manayathu Sasi. Additional phrases and learning activities are a starter curriculum, not a certified language course.</p><p>“Hear it” plays included Malayalam speech clips, generated from native Malayalam text with the <a href="https://huggingface.co/rhasspy/piper-voices/tree/main/ml/ml_IN/arjun/medium" target="_blank" rel="noopener">Piper Arjun Malayalam voice</a>. Normal and slower versions are included. The voice is synthesized, and regional pronunciation may vary. No voice installation or live speech API is needed. Record and replay practice is a self-check, without automated pronunciation grading.</p>${breakdownSources()}<p class="sourcefoot">Progress stays in this browser. Microphone recordings stay on your device and are cleared when the practice window closes. You can practise as a guest. An optional account syncs your streak. Browser fonts and linked reference pages may need internet access.</p></div><div class="modalfoot"><p>One small conversation at a time.</p><button class="btn" data-action="close">Let’s talk ${icon('arrow')}</button></div>`)}
function savePhrase(id){if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else state.saved.push(id);persist();const saved=state.saved.includes(id);render();$$(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',String(saved));if(!b.classList.contains('iconbtn'))b.textContent=saved?'✓ Saved':'Save phrase'});toast(saved?'Saved to your pocket.':'Phrase removed from saved.')}
function exportProgress(){const url=URL.createObjectURL(new Blob([JSON.stringify({app:'parayu',version:1,state},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='parayu-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function importProgress(file){if(!file)return;if(file.size>1e6){toast('This backup is too large. Choose a Parayu progress file.');return}file.text().then(t=>{const b=JSON.parse(t),s=b.state;const valid=b.app==='parayu'&&b.version===1&&s&&Number.isSafeInteger(s.xp)&&s.xp>=0&&[15,30,60].includes(s.goal)&&Array.isArray(s.completed)&&s.completed.every(x=>/^[0-5]-[0-2]$/.test(x))&&Array.isArray(s.saved)&&s.saved.every(x=>Number.isInteger(x)&&x>=0&&x<phrases.length)&&s.days&&typeof s.days==='object'&&!Array.isArray(s.days)&&Object.entries(s.days).every(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isSafeInteger(v)&&v>=0)&&s.reviews&&typeof s.reviews==='object'&&!Array.isArray(s.reviews)&&Object.entries(s.reviews).every(([k,v])=>/^\d+$/.test(k)&&Number(k)<36&&Number.isFinite(v)&&v>=0);if(!valid)throw Error();if(s.savedWords!==undefined&&(!Array.isArray(s.savedWords)||!s.savedWords.every(id=>typeof id==='string'&&(window.PARAYU_CONTENT?.vocabulary||[]).some(w=>w.id===id))))throw Error();const next={savedWords:[...new Set(s.savedWords||[])],xp:s.xp,completed:[...new Set(s.completed)],saved:[...new Set(s.saved)],goal:s.goal,days:s.days,guestDays:s.guestDays&&typeof s.guestDays==='object'&&!Array.isArray(s.guestDays)?Object.fromEntries(Object.entries(s.guestDays).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isSafeInteger(v)&&v>0)):{...s.days},reviews:s.reviews};openDialog(`${modalHeader('Restore your journey')}<h2>Replace this browser’s progress?</h2><p class="muted" style="margin:15px 0 28px">The backup contains ${next.completed.length} completed lessons and ${next.xp} XP.</p><div class="modalfoot"><button class="btn light" data-action="close">Keep current progress</button><button class="btn" id="confirm-import">Restore backup</button></div>`);$('#confirm-import').onclick=()=>{state=next;persist();closeDialog();render();toast('Your journey is restored.')}}).catch(()=>toast('That isn’t a valid Parayu progress backup.'))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.word!==undefined){addWord(+d.word);return}if(d.removeWord!==undefined){if(session&&!session.answered){session.wordOrder=session.wordOrder.filter(i=>i!==+d.removeWord);renderWordOrder()}return}if(d.travelCategory!==undefined){travelCategory=+d.travelCategory;renderTravelBody();return}if(d.nav){navigate(d.nav);return}if(d.unit!==undefined){openUnit(+d.unit);return}if(d.start){const[u,l]=d.start.split('-').map(Number);startLesson(u,l);return}if(d.filter){filter=d.filter;render();return}if(d.save!==undefined){savePhrase(+d.save);return}if(d.speak!==undefined){speak(d.speak==='mazha'?'mazha':+d.speak);return}if(d.slow!==undefined){speak(d.slow==='mazha'?'mazha':+d.slow,true);return}if(d.phrase!==undefined){session=null;openPhrase(+d.phrase);return}if(d.answer!==undefined){answer(+d.answer,b);return}if(d.role!==undefined){startRole(+d.role);return}if(d.roleAnswer!==undefined){roleAnswer(+d.roleAnswer,b);return}if(d.review){rateReview(d.review==='good');return}
 const a=d.action;if(a==='audio-stop')stopPronunciation();else if(a==='close')closeDialog();else if(a==='lesson-next')lessonNext();else if(a==='check-words')checkWords();else if(a==='clear-words'){if(session&&!session.answered){session.wordOrder=[];renderWordOrder()}}else if(a==='next-lesson'){const[u,l]=nextLesson();startLesson(u,l)}else if(a==='record')toggleRecording();else if(a==='role-next')roleNext();else if(a==='start-review')startReview();else if(a==='reveal')revealReview();else if(a==='travel')openTravel();else if(a==='saved-phrases'){filter='saved';query='';navigate('phrasebook')}else if(a==='about')about();else if(a==='export')exportProgress();else if(a==='import')$('#import-file').click();else if(a==='reset')openDialog(`${modalHeader('A fresh start')}<h2>Reset your journey?</h2><p class="muted" style="margin:16px 0 26px">This removes your lessons, XP, review schedule, saved phrases, and saved vocabulary from this browser. Your account’s streak is stored separately. Export a backup first if you’d like to keep them.</p><div class="modalfoot"><button class="btn light" data-action="close">Keep my progress</button><button class="btn peach" data-action="confirm-reset">Reset progress</button></div>`);else if(a==='confirm-reset'){state={xp:0,completed:[],saved:[],savedWords:[],days:{},guestDays:{},reviews:{},goal:30};persist();closeDialog();render();toast('A fresh little start.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#phrase-list').innerHTML=phraseResults();if($('#phrase-count'))$('#phrase-count').textContent=filteredPhrases().length+' of '+phrases.length+' phrases'}});
document.addEventListener('change',e=>{if(e.target.id==='goal'){state.goal=+e.target.value;persist();render();toast('Daily goal updated.')}if(e.target.id==='import-file')importProgress(e.target.files[0])});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
