let travelCategory=1;
const travelIds={0:[0,1,2,5],1:[6,7,8,10,11,23],2:[13,14,15,16,17],3:[18,19,20,21,22],4:[24,25,26,28,29],5:[30,31,32,33,34,35]};
function openTravel(){session=null;openDialog(`${modalHeader('TRAVEL MODE')}<div class="travel-heading"><span class="travel-icon">${icon('auto')}</span><h1>Out and about?</h1><p>Pick the moment. Keep the words close.</p></div><div class="chips travel-chips">${units.map((u,i)=>`<button class="chip ${travelCategory===i?'active':''}" data-travel-category="${i}">${u.short}</button>`).join('')}</div><div id="travel-body"></div><div class="notice">Tap “Hear it” for the included Malayalam voice, or show the large Latin phrase. No exercise, no score, just the words you need.</div>`);renderTravelBody()}
function renderTravelBody(){const container=$('#travel-body');if(!container)return;$$('[data-travel-category]').forEach(b=>{const selected=+b.dataset.travelCategory===travelCategory;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});container.innerHTML=travelIds[travelCategory].map(id=>{const p=phrases[id];return `<article class="travel-phrase"><p>${p.english}</p><h2>${p.latin}</h2><div class="phonetic">${p.say}</div><button class="textbtn" data-speak="${id}">${icon('sound')} Hear it</button></article>`}).join('')}
